    "nombre": "Asignación/Recepción o Devolución de Activos Fijos",
    "abreviacion": "AODAF",
    "plantilla": "[{\"type\":\"cite\",\"templateOptions\":{\"labelCite\":\"CITE\",\"labelFecha\":\"FECHA\",\"tipo\":\"general\",\"numeracionPagina\":\"false\",\"tipoHoja\":\"Letter\"}},{\"type\":\"select\",\"key\":\"inputSelect\",\"templateOptions\":{\"label\":\"Clasificación\",\"multiple\":false,\"labelProp\":\"value\",\"valueProp\":\"id\",\"showItem\":true,\"options\":[{\"value\":\"Reservado\",\"id\":\"Reservado\"},{\"value\":\"Secreto\",\"id\":\"Secreto\"},{\"value\":\"Confidencial\",\"id\":\"Confidencial\"},{\"value\":\"Desclasificado\",\"id\":\"Desclasificado\"}],\"disabled\":false,\"required\":true}},{\"type\":\"texto\",\"key\":\"texto\",\"templateOptions\":{\"label\":\"ASIGNACIÓN/RECEPCIÓN O DEVOLUCIÓN DE ACTIVOS FIJOS\",\"tipo\":\"h2\",\"className\":\"ap-text-center\",\"mTop\":true,\"mBot\":true}},{\"type\":\"datosGenerales\",\"key\":\"datosGenerales\",\"templateOptions\":{\"labelw\":10,\"labelRef\":\"REF.:\",\"showItem\":true,\"show\":{\"para\":true,\"via\":false,\"de\":true,\"ref\":false}}},{\"type\":\"checkbox\",\"key\":\"inputCheckBox\",\"templateOptions\":{\"label\":\"ASIGNACIÓN/RECEPCIÓN\",\"disabled\":false}},{\"type\":\"texto\",\"key\":\"parrafo\",\"templateOptions\":{\"label\":\"Profesional  de Activos Fijos y Almacén/Responsable Administrativo Financiero: Se ha realizado la asignación de Activos fijos según detalle.\",\"tipo\":\"p\",\"className\":\"ap-text-justify\",\"mTop\":false,\"mBot\":true}},{\"type\":\"texto\",\"key\":\"parrafo\",\"templateOptions\":{\"label\":\"Servidor Público/Consultor Individual de Línea: Recibí conforme los Activos fijos de acuerdo a lo especificado según detalle.\",\"tipo\":\"p\",\"className\":\"ap-text-justify\",\"mTop\":false,\"mBot\":true}},{\"type\":\"texto\",\"key\":\"parrafo\",\"templateOptions\":{\"label\":\"El servidor público deberá tomar en cuenta las siguientes prohibiciones y obligaciones:\",\"tipo\":\"p\",\"className\":\"ap-text-justify\",\"mTop\":false,\"mBot\":true}},{\"type\":\"texto\",\"key\":\"parrafo\",\"templateOptions\":{\"label\":\"Prohibiciones:\",\"tipo\":\"p\",\"className\":\"ap-text-justify\",\"mTop\":false,\"mBot\":false}},{\"type\":\"texto\",\"key\":\"parrafo\",\"templateOptions\":{\"label\":\"1. Usar los bienes para beneficio particular o privado; \\n2. Permitir el uso para beneficio particular o privado; \\n3. Prestar o transferir el bien a otro empleado público; \\n4. Enajenar el bien por cuenta propia; \\n5. Dañar o alterar sus características físicas o técnicas; \\n6. Poner en riesgo el bien; \\n7. Ingresar bienes particulares sin autorización de la Unidad Administrativa Financiera; \\n8. Sacar bienes de la entidad sin autorización de la Unidad Administrativa Financiera;\",\"tipo\":\"p\",\"className\":\"ap-text-justify\",\"mTop\":true,\"mBot\":true}},{\"type\":\"texto\",\"key\":\"parrafo\",\"templateOptions\":{\"label\":\"Obligaciones:\",\"tipo\":\"p\",\"className\":\"ap-text-justify\",\"mTop\":false,\"mBot\":false}},{\"type\":\"texto\",\"key\":\"parrafo\",\"templateOptions\":{\"label\":\"1. Comunicar al Área Administrativa Financiera cualquier desperfecto o falla en el bien que requiera mantenimiento; \\n2. Solicitar el respectivo formulario para la salida de activos fuera de la institución; \\n3. Comunicar de manera inmediata cualquier pérdica, robo o hurto a la Unidad Administrativa Financiera;\",\"tipo\":\"p\",\"className\":\"ap-text-justify\",\"mTop\":true,\"mBot\":true}},{\"type\":\"texto\",\"key\":\"parrafo\",\"templateOptions\":{\"label\":\"La no observancia a éstas prohibiciones y obligaciones generará responsabilidades establecidas en la Ley N° 1178 y sus reglamentos.\",\"tipo\":\"p\",\"className\":\"ap-text-justify\",\"mTop\":false,\"mBot\":true}},{\"type\":\"checkbox\",\"key\":\"inputCheckBox\",\"templateOptions\":{\"label\":\"DEVOLUCIÓN\",\"disabled\":false}},{\"type\":\"texto\",\"key\":\"parrafo\",\"templateOptions\":{\"label\":\"Profesional de Activos Fijos y Almacén/Responsable Administrativo Financiero: Se ha realizado la recepción de Activos Fijos devueltos según detalle.\",\"tipo\":\"p\",\"className\":\"ap-text-justify\",\"mTop\":false,\"mBot\":true}},{\"type\":\"tablaActivos\",\"key\":0,\"templateOptions\":{\"label\":\"Tabla de Activos Fijos\",\"tipoFormulario\":\"ASIGNACION_DEVOLUCION\"}},{\"type\":\"texto\",\"key\":\"parrafo\",\"templateOptions\":{\"label\":\"Servidor Público/Consultor Individual de Linea: Se ha realizado la devolución de activos según detalle.\",\"tipo\":\"p\",\"className\":\"ap-text-justify\",\"mTop\":true,\"mBot\":true}},{\"type\":\"archivo\",\"key\":\"archivo\",\"templateOptions\":{\"label\":\"Elegir PDF\",\"multiple\":true}},{\"type\":\"ccArchivo\",\"key\":\"ccArchivo\",\"templateOptions\":{\"labelw\":10,\"label\":\"CC/Archivo:\"}}]",
