    "plantilla": "[{\"type\":\"cite\",\"templateOptions\":{\"labelCite\":\"CITE\",\"labelFecha\":\"FECHA\",\"tipo\":\"general\",\"numeracionPagina\":\"false\",\"tipoHoja\":\"Letter\"}},{\"type\":\"select\",\"key\":\"inputSelect\",\"templateOptions\":{\"label\":\"\",\"multiple\":false,\"labelProp\":\"value\",\"valueProp\":\"id\",\"showItem\":true,\"options\":[{\"value\":\"Reservado\",\"id\":\"Reservado\"},{\"value\":\"Secreto\",\"id\":\"Secreto\"},{\"value\":\"Confidencial\",\"id\":\"Confidencial\"},{\"value\":\"Desclasificado\",\"id\":\"Desclasificado\"}],\"disabled\":false,\"required\":true}},{\"type\":\"texto\",\"key\":\"texto\",\"templateOptions\":{\"label\":\"CERTIFICADO DE CONCLUSIÓN DE VOLUNTARIADO\",\"tipo\":\"h2\",\"className\":\"ap-text-center\",\"mTop\":true,\"mBot\":true}},{\"type\":\"datosGenerales\",\"key\":\"datosGenerales\",\"templateOptions\":{\"labelw\":10,\"labelRef\":\"REF.:\",\"showItem\":false,\"show\":{\"para\":true,\"via\":true,\"de\":true,\"ref\":true}}},{\"type\":\"texto\",\"key\":\"parrafo\",\"templateOptions\":{\"label\":\"La Agencia de Gobierno Electrónico Tecnologías de Información y Comunicación (AGETIC) certifica que:\",\"tipo\":\"p\",\"className\":\"ap-text-justify\",\"mTop\":true,\"mBot\":true}},{\"type\":\"textarea\",\"key\":\"inputTextArea\",\"templateOptions\":{\"label\":\"\",\"rows\":1,\"grow\":false,\"required\":true}},{\"type\":\"textarea\",\"key\":\"inputTextArea\",\"templateOptions\":{\"label\":\"\",\"rows\":1,\"grow\":false,\"required\":true}},{\"type\":\"texto\",\"key\":\"parrafo\",\"templateOptions\":{\"label\":\"Según el DS. 3900 de 15 de mayo de 2019 en su artículo tercero, parágrafo segundo: el voluntariado social juvenil comunitario podrá ser acreditado administrativamente en calidad de pasantía. Así mismo, el reglamento específico para la incorporación de voluntarios al programa de inclusión digital aprobado mediante resolución administrativa AGETIC/RA/0064/2019 de 17 de septiembre de 2019 especifica en el artículo 16, parágrafo segundo “En caso de estudiantes de últimos años o egresados, podrán solicitar una certificación específica de pasantía a fin de acreditación académica en la Universidad a la que pertenezca.”\",\"tipo\":\"p\",\"className\":\"ap-text-justify\",\"mTop\":true,\"mBot\":true}},{\"type\":\"texto\",\"key\":\"parrafo\",\"templateOptions\":{\"label\":\"En consideración a la normativa citada y de acuerdo al Convenio de Inclusión Digital suscrito con su persona se emite el presente certificado, firmado digitalmente cuya validez está respaldada por la Ley 164 de 2011 y el DS. 3525 de 2018.\",\"tipo\":\"p\",\"className\":\"ap-text-justify\",\"mTop\":true,\"mBot\":true}},{\"type\":\"ccArchivo\",\"key\":\"ccArchivo\",\"templateOptions\":{\"labelw\":10,\"label\":\"CC/Archivo:\"}}]",
