    "plantilla": "[{\"type\":\"select\",\"key\":\"inputSelect\",\"templateOptions\":{\"label\":\"Clasificación\",\"multiple\":false,\"labelProp\":\"value\",\"valueProp\":\"id\",\"showItem\":true,\"options\":[{\"value\":\"Reservado\",\"id\":\"Reservado\"},{\"value\":\"Secreto\",\"id\":\"Secreto\"},{\"value\":\"Confidencial\",\"id\":\"Confidencial\"},{\"value\":\"Desclasificado\",\"id\":\"Desclasificado\"}],\"disabled\":false,\"required\":true}},{\"type\":\"cite\",\"key\":0,\"templateOptions\":{\"labelCite\":\"CITE\",\"labelFecha\":\"FECHA\",\"tipo\":\"general\",\"numeracionPagina\":\"false\",\"tipoHoja\":\"Letter\",\"tipoMembrete\":\"sin membrete\"}},{\"type\":\"texto\",\"key\":\"texto\",\"templateOptions\":{\"label\":\"DICTAMEN DE PROYECTO\",\"tipo\":\"h2\",\"className\":\"ap-text-center\",\"mTop\":true,\"mBot\":true}},{\"type\":\"texto\",\"key\":\"texto\",\"templateOptions\":{\"label\":\"1. CÓDIGO:\",\"tipo\":\"h3\",\"className\":\"ap-text-left\",\"mTop\":true,\"mBot\":false}},{\"type\":\"editorTexto\",\"templateOptions\":{\"label\":\"jojojo\"}},{\"type\":\"texto\",\"key\":\"texto\",\"templateOptions\":{\"label\":\"2. NOMBRE DEL PROYECTO:\",\"tipo\":\"h3\",\"className\":\"ap-text-left\",\"mTop\":true,\"mBot\":false}},{\"type\":\"textarea\",\"key\":\"inputTextArea\",\"templateOptions\":{\"label\":\"\",\"rows\":2,\"grow\":false,\"required\":true}},{\"type\":\"texto\",\"key\":\"texto\",\"templateOptions\":{\"label\":\"3. FASES Y RESPONSABILIDADES\",\"tipo\":\"h3\",\"className\":\"ap-text-left\",\"mTop\":true,\"mBot\":true}},{\"type\":\"editorTexto\",\"templateOptions\":{\"label\":\"jojojo\"}},{\"type\":\"editorTexto\",\"templateOptions\":{\"label\":\"jojojo\"}},{\"type\":\"texto\",\"key\":\"texto\",\"templateOptions\":{\"label\":\"4. JUSTIFICACIÓN\",\"tipo\":\"h3\",\"className\":\"ap-text-left\",\"mTop\":true,\"mBot\":false}},{\"type\":\"texto\",\"key\":\"texto\",\"templateOptions\":{\"label\":\"4.1. Breve explicación sobre la necesidad del proyecto\",\"tipo\":\"h3\",\"className\":\"ap-text-left\",\"mTop\":true,\"mBot\":false}},{\"type\":\"textarea\",\"key\":\"inputTextArea\",\"templateOptions\":{\"label\":\"\",\"rows\":2,\"grow\":false,\"required\":true}},{\"type\":\"texto\",\"key\":\"texto\",\"templateOptions\":{\"label\":\"4.2. El proyecto esta articulado:\",\"tipo\":\"h3\",\"className\":\"ap-text-left\",\"mTop\":true,\"mBot\":false}},{\"type\":\"select\",\"key\":\"inputSelect\",\"templateOptions\":{\"label\":\"PEI AGETIC (2016-2020) - Objetivo Estratégico\",\"multiple\":false,\"labelProp\":\"value\",\"valueProp\":\"id\",\"showItem\":true,\"options\":[{\"value\":\"1. Fortalecer institucionalmente a la AGETIC y posicionarla como líder en el desarrollo y aplicación de Gobierno Electrónico y Tecnologías de la Información y Comunicación\",\"id\":\"1. Fortalecer institucionalmente a la AGETIC y posicionarla como líder en el desarrollo y aplicación de Gobierno Electrónico y Tecnologías de la Información y Comunicación\"},{\"value\":\"2. Aportar a la construcción de una Gestión Pública Integrada, eficiente, transparente y participativa orientada al servicio e interacción con la ciudadanía, a partir de la implementación de Gobierno Electrónico y el despliegue de infraestructura TIC\",\"id\":\"2. Aportar a la construcción de una Gestión Pública Integrada, eficiente, transparente y participativa orientada al servicio e interacción con la ciudadanía, a partir de la implementación de Gobierno Electrónico y el despliegue de infraestructura TIC\"},{\"value\":\"3. Generar políticas, herramientas y acciones referentes a Seguridad de la Información para proteger los datos e información de las instituciones del Estado y la Población\",\"id\":\"3. Generar políticas, herramientas y acciones referentes a Seguridad de la Información para proteger los datos e información de las instituciones del Estado y la Población\"},{\"value\":\"4. Desarrollar políticas, programas, proyectos y acciones relacionadas a las TIC's para mejorar la calidad de vida de las ciudadanas y ciudadanos.\",\"id\":\"4. Desarrollar políticas, programas, proyectos y acciones relacionadas a las TIC's para mejorar la calidad de vida de las ciudadanas y ciudadanos.\"},{\"value\":\"5. Impulsar la soberanía tecnológica a través de la generación de procesos de investigación, innovación y desarrollo para aportar a la producción de conocimiento y tecnología\",\"id\":\"5. Impulsar la soberanía tecnológica a través de la generación de procesos de investigación, innovación y desarrollo para aportar a la producción de conocimiento y tecnología\"}],\"disabled\":false,\"required\":true}},{\"type\":\"editorTexto\",\"templateOptions\":{\"label\":\"jojojo\"}},{\"type\":\"editorTexto\",\"templateOptions\":{\"label\":\"jojojo\"}},{\"type\":\"texto\",\"key\":\"texto\",\"templateOptions\":{\"label\":\"4.3. Otros (sí corresponde):\",\"tipo\":\"h3\",\"className\":\"ap-text-left\",\"mTop\":true,\"mBot\":false}},{\"type\":\"select\",\"key\":\"inputSelect\",\"templateOptions\":{\"label\":\"Denominación Plan\",\"multiple\":false,\"labelProp\":\"value\",\"valueProp\":\"id\",\"showItem\":true,\"options\":[{\"value\":\"Plan Institucional de Gobierno Electrónico (2018-2020)\",\"id\":\"Plan Institucional de Gobierno Electrónico (2018-2020)\"},{\"value\":\"Plan Institucional de Implementación de Software Libre y Estándares Abiertos (2019-2020)\",\"id\":\"Plan Institucional de Implementación de Software Libre y Estándares Abiertos (2019-2020)\"},{\"value\":\"Plan Institucional de Seguridad de Información (2019-2020)\",\"id\":\"Plan Institucional de Seguridad de Información (2019-2020)\"}],\"disabled\":false,\"required\":true}},{\"type\":\"editorTexto\",\"key\":0,\"templateOptions\":{\"label\":\"jojojo\"}},{\"type\":\"texto\",\"key\":\"texto\",\"templateOptions\":{\"label\":\"5. ENTIDAD O UNIDAD ORGANIZACIONAL BENEFICIARIA DEL PROYECTO:\",\"tipo\":\"h3\",\"className\":\"ap-text-left\",\"mTop\":true,\"mBot\":false}},{\"type\":\"editorTexto\",\"templateOptions\":{\"label\":\"jojojo\"}},{\"type\":\"texto\",\"key\":\"texto\",\"templateOptions\":{\"label\":\"6. DICTAMEN\",\"tipo\":\"h3\",\"className\":\"ap-text-left\",\"mTop\":true,\"mBot\":false}},{\"type\":\"texto\",\"key\":\"parrafo\",\"templateOptions\":{\"label\":\"Con base a la información anterior se decide, INICIAR el proyecto por lo que, La Máxima Autoridad Ejecutiva de la Entidad y el responsable del proyecto certifican la información aquí registrada, se responsabilizan por la asignación de recursos que requiera el proyecto y los resultados a ser alcanzados por éste.\",\"tipo\":\"p\",\"className\":\"ap-text-justify\",\"mTop\":true,\"mBot\":true}},{\"type\":\"editorTexto\",\"templateOptions\":{\"label\":\"jojojo\"}},{\"type\":\"editorTexto\",\"templateOptions\":{\"label\":\"jojojo\"}},{\"type\":\"vacio\",\"key\":0,\"templateOptions\":{\"height\":\"0.5\",\"style\":{\"height\":\"0.5cm\"}}},{\"type\":\"datosGenerales\",\"key\":\"datosGenerales\",\"templateOptions\":{\"labelw\":10,\"labelRef\":\"REF.:\",\"showItem\":false,\"show\":{\"para\":true,\"via\":true,\"de\":true,\"ref\":true}}},{\"type\":\"ccArchivo\",\"key\":\"ccArchivo\",\"templateOptions\":{\"labelw\":10,\"label\":\"CC/Archivo:\"}}]",
